export type IconName = "chevron-up" | "chevron-down" | "chevron-left" | "chevron-right" | "arrow-right" | "arrow-up" | "close" | "check" | "search" | "account" | "hamburger" | "bag" | "social-facebook" | "social-instagram" | "social-youtube" | "social-tiktok" | "play" | "pause" | "location" | "info" | "logo-full" | "logo-bear" | "crown" | "shop-account" | "heart-outline" | "filled-heart" | "plus" | "minus" | "shipping" | "guarantee" | "leak-proof" | "question";

export function SpriteSheet() {
  return (
    <svg
      aria-hidden="true"
      xmlns="http://www.w3.org/2000/svg"
      style={{ display: "none" }}
      dangerouslySetInnerHTML={{ __html: SPRITE_MARKUP }}
    />
  );
}

interface IconProps {
  name: IconName;
  size?: number | string;
  className?: string;
}

/** Renders an icon from the embedded sprite via <use href="#name">. */
export function Icon({ name, size = 24, className }: IconProps) {
  return (
    <svg
      aria-hidden="true"
      role="img"
      className={cn("shrink-0 fill-current", className)}
      width={size}
      height={size}
      viewBox={VIEWBOXES[name]}
    >
      <use href={`#${name}`} />
    </svg>
  );
}
